func init() { slots.Keywords.Bind(&KeywordsMeta) }

func init() {
	KeywordsMeta.Edges = keywords.EdgeMetas()
	KeywordsMeta.Edges[0].Owner, KeywordsMeta.Edges[0].Target = &KeywordsMeta, &FieldMeta
	KeywordsMeta.Edges[1].Owner, KeywordsMeta.Edges[1].Target = &KeywordsMeta, &FieldMeta
	KeywordsMeta.Edges[2].Owner, KeywordsMeta.Edges[2].Target = &KeywordsMeta, &FieldMeta
	KeywordsMeta.Edges[3].Owner, KeywordsMeta.Edges[3].Target = &KeywordsMeta, &FieldMeta
	KeywordsMeta.Edges[4].Owner, KeywordsMeta.Edges[4].Target = &KeywordsMeta, &FieldMeta
}
